import React, { useState, useCallback, useRef } from 'react';
import './index.css';
import Cursor from './components/Cursor';
import DrawCanvas from './components/DrawCanvas';
import TypeRenderer from './components/TypeRenderer';
import MetricDisplay from './components/MetricDisplay';
import { analysePath, metricsToType } from './hooks/pathAnalysis';

const PRESET_WORDS = ['FORM', 'DRAPE', 'BODY', 'VOID', 'SEAM'];

export default function App() {
  const [metrics,  setMetrics]  = useState(null);
  const [typeProps,setTypeProps]= useState(null);
  const [word,     setWord]     = useState('FORM');
  const [input,    setInput]    = useState('FORM');
  const [hasDrawn, setHasDrawn] = useState(false);
  const canvasRef = useRef(null);

  const onPathUpdate = useCallback((pts) => {
    if (pts.length < 8) { setMetrics(null); setTypeProps(null); setHasDrawn(false); return; }
    const m = analysePath(pts);
    const t = metricsToType(m);
    setMetrics(m);
    setTypeProps(t);
    setHasDrawn(true);
  }, []);

  const handleClear = () => {
    canvasRef.current?.clear();
    setMetrics(null); setTypeProps(null); setHasDrawn(false);
  };

  const applyWord = () => {
    const clean = input.toUpperCase().replace(/[^A-Z]/g, '').slice(0, 10);
    if (clean) setWord(clean);
  };

  return (
    <>
      <Cursor />

      {/* ── Nav ── */}
      <nav style={{
        position:'fixed', top:0, left:0, right:0, zIndex:100,
        display:'flex', alignItems:'center', justifyContent:'space-between',
        padding:'0 40px', height:52,
        background:'rgba(8,8,8,0.97)',
        borderBottom:'1px solid rgba(255,255,255,0.07)',
        backdropFilter:'blur(12px)',
      }}>
        <div style={{ display:'flex', alignItems:'center', gap:20 }}>
          <span style={{ fontSize:13, fontWeight:700, letterSpacing:'0.12em', textTransform:'uppercase', color:'#fff' }}>
            Silhouette
          </span>
          <span style={{ width:1, height:14, background:'rgba(255,255,255,0.15)', display:'inline-block' }} />
          <span style={{ fontSize:11, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(255,255,255,0.35)', fontFamily:'monospace' }}>
            Generative Type
          </span>
        </div>
        <div style={{ display:'flex', alignItems:'center', gap:24 }}>
          <span style={{ fontSize:11, fontFamily:'monospace', color:'rgba(255,255,255,0.3)', letterSpacing:'0.1em' }}>
            Sandra Sæbø · 2024
          </span>
          <a href="https://your-portfolio-url.vercel.app" style={{ fontSize:11, letterSpacing:'0.14em', textTransform:'uppercase', padding:'6px 16px', border:'1px solid rgba(255,255,255,0.15)', color:'rgba(255,255,255,0.5)', transition:'all .25s' }}
            onMouseEnter={e=>{e.currentTarget.style.borderColor='rgba(255,255,255,0.5)';e.currentTarget.style.color='#fff'}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor='rgba(255,255,255,0.15)';e.currentTarget.style.color='rgba(255,255,255,0.5)'}}>
            ← Portfolio
          </a>
        </div>
      </nav>

      <main style={{ paddingTop:52 }}>

        {/* ── Big intro — full width, lots of space ── */}
        <div style={{
          padding:'80px 40px 72px',
          borderBottom:'1px solid rgba(255,255,255,0.07)',
          animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both',
        }}>
          <h1 style={{
            fontFamily:'Helvetica Neue,Helvetica,Arial,sans-serif',
            fontWeight:700,
            fontSize:'clamp(56px,11vw,160px)',
            letterSpacing:'-0.05em',
            lineHeight:0.85,
            textTransform:'uppercase',
            color:'#fff',
            marginBottom:36,
          }}>
            Draw.<br/>
            <span style={{ color:'rgba(255,255,255,0.2)' }}>Type follows.</span>
          </h1>
          <p style={{ fontSize:15, color:'rgba(255,255,255,0.45)', lineHeight:1.8, fontWeight:300, maxWidth:480 }}>
            Sketch any silhouette — a garment, a body, a gesture. The algorithm reads its geometry and selects a typeface that matches its character.
          </p>
        </div>

        {/* ── Type output — always visible, dark ── */}
        <div style={{
          background:'#080808',
          borderBottom:'1px solid rgba(255,255,255,0.07)',
          minHeight:220,
          display:'flex', alignItems:'center',
          padding:'0',
          position:'relative',
          overflow:'hidden',
        }}>
          {/* Scanline texture */}
          <div style={{ position:'absolute', inset:0, background:'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(255,255,255,0.012) 2px, rgba(255,255,255,0.012) 4px)', pointerEvents:'none', zIndex:1 }} />

          {!hasDrawn && (
            <div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center', zIndex:2, pointerEvents:'none' }}>
              <p style={{ fontSize:12, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.18)', fontFamily:'monospace', animation:'pulse 3s infinite' }}>
                Draw a silhouette below
              </p>
            </div>
          )}

          <div style={{ width:'100%', height:220, position:'relative', zIndex:2 }}>
            <TypeRenderer metrics={metrics} word={word} />
          </div>

          {hasDrawn && (
            <div style={{ position:'absolute', top:16, right:20, display:'flex', alignItems:'center', gap:8, zIndex:3 }}>
              <span style={{ width:5, height:5, borderRadius:'50%', background:'rgba(255,255,255,0.5)', display:'inline-block', animation:'pulse 2s infinite' }} />
              <span style={{ fontSize:10, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', fontFamily:'monospace' }}>Live</span>
            </div>
          )}
        </div>

        {/* ── Controls ── */}
        <div style={{
          padding:'16px 40px',
          borderBottom:'1px solid rgba(255,255,255,0.07)',
          display:'flex', alignItems:'center', gap:20, flexWrap:'wrap', justifyContent:'space-between',
          background:'rgba(255,255,255,0.02)',
        }}>
          {/* Word input */}
          <div style={{ display:'flex', alignItems:'center', gap:14 }}>
            <span style={{ fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', fontFamily:'monospace' }}>Word</span>
            <input value={input} onChange={e=>setInput(e.target.value.toUpperCase().slice(0,10))} onKeyDown={e=>e.key==='Enter'&&applyWord()} placeholder="FORM"
              style={{ background:'transparent', border:'none', borderBottom:'1px solid rgba(255,255,255,0.15)', color:'#fff', fontFamily:'monospace', fontSize:13, letterSpacing:'0.12em', padding:'4px 0', width:100, outline:'none', textTransform:'uppercase' }} />
            <button onClick={applyWord} data-hover style={{ fontSize:10, letterSpacing:'0.16em', textTransform:'uppercase', padding:'5px 14px', border:'1px solid rgba(255,255,255,0.15)', color:'rgba(255,255,255,0.5)', transition:'all .2s', fontFamily:'monospace' }}
              onMouseEnter={e=>{e.currentTarget.style.background='#fff';e.currentTarget.style.color='#080808'}}
              onMouseLeave={e=>{e.currentTarget.style.background='transparent';e.currentTarget.style.color='rgba(255,255,255,0.5)'}}>Apply</button>
          </div>

          {/* Presets */}
          <div style={{ display:'flex', gap:6 }}>
            {PRESET_WORDS.map(w=>(
              <button key={w} onClick={()=>{setWord(w);setInput(w);}} data-hover
                style={{ fontSize:10, letterSpacing:'0.12em', textTransform:'uppercase', padding:'5px 12px', border:`1px solid ${word===w?'rgba(255,255,255,0.4)':'rgba(255,255,255,0.1)'}`, color:word===w?'#fff':'rgba(255,255,255,0.35)', background:word===w?'rgba(255,255,255,0.07)':'transparent', transition:'all .2s', fontFamily:'monospace' }}>
                {w}
              </button>
            ))}
          </div>

          {/* Clear */}
          <button onClick={handleClear} data-hover style={{ fontSize:10, letterSpacing:'0.16em', textTransform:'uppercase', padding:'5px 14px', border:'1px solid rgba(255,255,255,0.1)', color:'rgba(255,255,255,0.35)', transition:'all .2s', fontFamily:'monospace' }}
            onMouseEnter={e=>{e.currentTarget.style.borderColor='rgba(255,255,255,0.35)';e.currentTarget.style.color='#fff'}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor='rgba(255,255,255,0.1)';e.currentTarget.style.color='rgba(255,255,255,0.35)'}}>Clear</button>
        </div>

        {/* ── Main: canvas left, metrics right ── */}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 300px', minHeight:520, borderBottom:'1px solid rgba(255,255,255,0.07)' }}>

          {/* Canvas */}
          <div style={{ borderRight:'1px solid rgba(255,255,255,0.07)', position:'relative', background:'#0c0c0c' }}>
            {!hasDrawn && (
              <div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center', pointerEvents:'none', zIndex:1 }}>
                <div style={{ textAlign:'center' }}>
                  <p style={{ fontSize:12, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(255,255,255,0.18)', marginBottom:8, fontFamily:'monospace' }}>Draw here</p>
                  <p style={{ fontSize:11, color:'rgba(255,255,255,0.12)', fontFamily:'monospace' }}>Any shape — garment, body, gesture</p>
                </div>
              </div>
            )}
            <DrawCanvas ref={canvasRef} onPathUpdate={onPathUpdate} width={900} height={600} />
          </div>

          {/* Metrics */}
          <div style={{ padding:'32px 28px', borderLeft:'none' }}>
            <MetricDisplay metrics={metrics} typeProps={typeProps} />

            {/* How it works */}
            <div style={{ marginTop:32, paddingTop:24, borderTop:'1px solid rgba(255,255,255,0.07)' }}>
              <p style={{ fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.25)', marginBottom:16, fontFamily:'monospace' }}>How it works</p>
              {[
                ['Curvature', 'Font weight 100–900'],
                ['Drape',     'Italic angle'],
                ['Tension',   'Vertical scale'],
                ['Asymmetry', 'Font selection'],
              ].map(([k,v]) => (
                <div key={k} style={{ display:'flex', justifyContent:'space-between', marginBottom:10 }}>
                  <span style={{ fontSize:11, color:'rgba(255,255,255,0.35)', fontFamily:'monospace' }}>{k}</span>
                  <span style={{ fontSize:11, color:'rgba(255,255,255,0.5)', fontFamily:'monospace' }}>→ {v}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* ── Footer ── */}
        <div style={{ padding:'24px 40px', display:'flex', justifyContent:'space-between', alignItems:'center', flexWrap:'wrap', gap:16 }}>
          <span style={{ fontSize:11, fontFamily:'monospace', color:'rgba(255,255,255,0.2)', letterSpacing:'0.1em' }}>
            Silhouette — Generative Typography System — 2024
          </span>
          <span style={{ fontSize:11, fontFamily:'monospace', color:'rgba(255,255,255,0.2)', letterSpacing:'0.1em' }}>
            Canvas API · Spring Physics · Variable Fonts
          </span>
        </div>
      </main>
    </>
  );
}
